import re


def entities(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    child_nodes = children(doc, scope_node)
    result = []
    for node in child_nodes:
        if 'Objects' in node['title'] and node['kind'] == 'list':
            for line in node['lines']:
                m = re.match(r'Object\s+(\d+):\s+(.*)', line)
                if m:
                    result.append({"id": m.group(1), "description": m.group(2)})
    return result


def recorded_end(doc, scope) -> float:
    scope_node = node_by_title(doc, scope)
    child_nodes = children(doc, scope_node)
    max_frame = -1
    for node in child_nodes:
        if 'Motion log' in node['title'] and node['kind'] == 'table':
            for _, row in table_rows(node):
                f = float(row['frame'])
                if f > max_frame:
                    max_frame = f
        if 'Events' in node['title'] and node['kind'] == 'list':
            for line in node['lines']:
                fm = re.match(r'Frame\s+(\d+)', line)
                if fm and int(fm.group(1)) > max_frame:
                    max_frame = int(fm.group(1))
    return float(max_frame) if max_frame >= 0 else None


def inputs(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    child_nodes = children(doc, scope_node)
    events_node = None
    for node in child_nodes:
        if 'Events' in node['title'] and node['kind'] == 'list':
            events_node = node
    if events_node is None:
        return []
    result = []
    iid = 0
    for idx, line in enumerate(events_node['lines']):
        fm = re.match(r'Frame\s+(\d+)', line)
        if not fm:
            continue
        frame = int(fm.group(1))
        if 'is in view when the video begins' in line or 'enters the scene' in line:
            obj_ids = re.findall(r'Object\s+(\d+)', line)
            for oid in obj_ids:
                result.append({
                    "id": f"inp_{iid}",
                    "time": float(frame),
                    "kind": "entry" if 'enters the scene' in line else "initial",
                    "entities": [oid],
                    "fields": {},
                    "src": [[events_node['node_id'], idx]]
                })
                iid += 1
    return result


def outcomes(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    child_nodes = children(doc, scope_node)
    events_node = None
    for node in child_nodes:
        if 'Events' in node['title'] and node['kind'] == 'list':
            events_node = node
    if events_node is None:
        return []
    result = []
    for idx, line in enumerate(events_node['lines']):
        fm = re.match(r'Frame\s+(\d+)', line)
        if not fm:
            continue
        frame = int(fm.group(1))
        if 'collid' in line.lower():
            obj_ids = re.findall(r'Object\s+(\d+)', line)
            result.append({
                "time": float(frame),
                "kind": "collision",
                "entities": obj_ids,
                "value": None,
                "src": [[events_node['node_id'], idx]]
            })
        if any(kw in line.lower() for kw in ['leaves the', 'exits the', 'exits.', 'no longer in view']):
            obj_ids = re.findall(r'Object\s+(\d+)', line)
            if obj_ids:
                result.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": obj_ids,
                    "value": None,
                    "src": [[events_node['node_id'], idx]]
                })
    return result


def params(doc, scope) -> dict:
    return {
        "stationary_speed_threshold": 0.1,
        "total_frames": 128
    }


