import math
import re


def simulate(doc, scope, inputs, params, start=None, horizon=None):
    scope_node = node_by_title(doc, scope)
    motion_node = None
    for node in children(doc, scope_node):
        if 'Motion log' in node['title'] and node['kind'] == 'table':
            motion_node = node
            break

    motion = {}
    if motion_node:
        for _, row in table_rows(motion_node):
            parts = row['object'].split()
            oid = parts[0]
            frame = float(row['frame'])
            motion.setdefault(oid, {})[frame] = {
                "x": float(row['x']), "y": float(row['y']),
                "vx": float(row['vx']), "vy": float(row['vy'])
            }

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0

    DT = 0.027
    FRIC = 0.993
    COL_DIST = 0.38
    COR = 0.5
    EXIT_B = 5.0
    SUB = 4

    dt_sub_frame = 1.0 / SUB
    dt_sub_sec = DT / SUB
    fric_sub = FRIC ** dt_sub_frame
    ln_fric = math.log(FRIC)

    entry_times = {}
    active = set()
    for inp in inputs:
        for oid in inp["entities"]:
            active.add(oid)
            entry_times[oid] = inp["time"]

    def propagate(ref_f, ref, target_f):
        dt = target_f - ref_f
        if abs(dt) < 1e-9:
            return ref["x"], ref["y"], ref["vx"], ref["vy"]
        vs = FRIC ** dt
        pos_factor = (FRIC ** dt - 1.0) / ln_fric
        x = ref["x"] + ref["vx"] * pos_factor * DT
        y = ref["y"] + ref["vy"] * pos_factor * DT
        vx = ref["vx"] * vs
        vy = ref["vy"] * vs
        return x, y, vx, vy

    state = {}
    pending = []

    for oid in active:
        if oid not in motion:
            continue

        et = entry_times.get(oid, 0)
        frames = sorted(motion[oid].keys())

        if et > start:
            ref_f = frames[0]
            ref = motion[oid][ref_f]
            x, y, vx, vy = propagate(ref_f, ref, et)
            pending.append({"oid": oid, "entry_time": et, "x": x, "y": y, "vx": vx, "vy": vy})
        else:
            valid = [f for f in frames if f <= start]
            if valid:
                ref_f = max(valid)
                ref = motion[oid][ref_f]
                x, y, vx, vy = propagate(ref_f, ref, start)
                state[oid] = {"x": x, "y": y, "vx": vx, "vy": vy}
            else:
                ref = motion[oid][frames[0]]
                state[oid] = {"x": ref["x"], "y": ref["y"], "vx": ref["vx"], "vy": ref["vy"]}

    outcomes = []
    exited = set()
    last_col = {}

    t = start
    while t <= horizon + dt_sub_frame:
        for p in pending:
            if t >= p["entry_time"] and p["oid"] not in state:
                state[p["oid"]] = {"x": p["x"], "y": p["y"], "vx": p["vx"], "vy": p["vy"]}
        pending = [p for p in pending if p["oid"] not in state]

        for oid in list(state.keys()):
            if oid in exited:
                continue
            s = state[oid]
            s["x"] += s["vx"] * dt_sub_sec
            s["y"] += s["vy"] * dt_sub_sec
            s["vx"] *= fric_sub
            s["vy"] *= fric_sub

            if abs(s["x"]) > EXIT_B or abs(s["y"]) > EXIT_B:
                if oid not in exited:
                    exited.add(oid)
                    outcomes.append({
                        "time": float(t), "kind": "exit",
                        "entities": [oid], "value": None, "src": None
                    })

        oids = [o for o in state if o not in exited]
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                o1, o2 = oids[i], oids[j]
                s1, s2 = state[o1], state[o2]
                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                d = math.hypot(dx, dy)

                if d < COL_DIST:
                    pair = tuple(sorted([o1, o2]))
                    lt = last_col.get(pair, -10)
                    if t - lt > 2.0:
                        last_col[pair] = t
                        outcomes.append({
                            "time": float(t), "kind": "collision",
                            "entities": [o1, o2], "value": None, "src": None
                        })

                        if d > 1e-6:
                            nx, ny = dx / d, dy / d
                            v1n = s1["vx"] * nx + s1["vy"] * ny
                            v2n = s2["vx"] * nx + s2["vy"] * ny

                            v1n_new = ((1 - COR) * v1n + (1 + COR) * v2n) / 2
                            v2n_new = ((1 + COR) * v1n + (1 - COR) * v2n) / 2

                            s1["vx"] += (v1n_new - v1n) * nx
                            s1["vy"] += (v1n_new - v1n) * ny
                            s2["vx"] += (v2n_new - v2n) * nx
                            s2["vy"] += (v2n_new - v2n) * ny

                            overlap = COL_DIST - d
                            sep = (overlap + 0.01) / 2.0
                            s1["x"] -= nx * sep
                            s1["y"] -= ny * sep
                            s2["x"] += nx * sep
                            s2["y"] += ny * sep

        t += dt_sub_frame

    outcomes.sort(key=lambda o: o["time"])
    return outcomes

