import re
import math
import numpy as np
from collections import defaultdict

def analyze_dynamics(doc):
    # Collect all motion data
    all_data = []
    for scope_title in [n['title'] for n in doc['nodes'] if n['level'] == 1 and 'Video' in n['title']]:
        scope_node = node_by_title(doc, scope_title)
        children_nodes = children(doc, scope_node)
        motion_node = None
        events_node = None
        objects_node = None
        for n in children_nodes:
            if 'Motion log' in n['title']: motion_node = n
            if 'Events' in n['title']: events_node = n
            if 'Objects' in n['title']: objects_node = n
        if not motion_node: continue

        # Get object properties
        obj_props = {}
        for line in objects_node['lines']:
            m = re.match(r'Object\s+(\d+):\s+(\w+)\s+(\w+)\s+(\w+)', line)
            if m:
                obj_props[m.group(1)] = {'color': m.group(2), 'material': m.group(3), 'shape': m.group(4)}

        rows = list(table_rows(motion_node))
        traj = defaultdict(list)
        for _, row in rows:
            parts = row['object'].split()
            oid = parts[0]
            traj[oid].append({
                'f': int(row['frame']), 'x': float(row['x']), 'y': float(row['y']),
                'vx': float(row['vx']), 'vy': float(row['vy']), 'speed': float(row['speed']),
                'props': obj_props.get(oid, {})
            })
        for oid in traj:
            traj[oid].sort(key=lambda r: r['f'])

        # Check entry velocities
        if events_node:
            for line in events_node['lines']:
                if 'enters the scene' in line or 'is in view when' in line:
                    fm = re.match(r'Frame\s+(\d+)', line)
                    f_entry = int(fm.group(1))
                    objs = re.findall(r'Object\s+(\d+)', line)
                    for oid in objs:
                        t_list = traj.get(oid, [])
                        for p in t_list:
                            if p['f'] == f_entry:
                                all_data.append({
                                    'scope': scope_title, 'type': 'entry',
                                    'f': f_entry, 'oid': oid, 'mat': p['props'].get('material'),
                                    'shape': p['props'].get('shape'),
                                    'vx': p['vx'], 'vy': p['vy'], 'speed': p['speed']
                                })
                                break

        # Check deceleration
        for oid, t_list in traj.items():
            for i in range(len(t_list)-1):
                p1, p2 = t_list[i], t_list[i+1]
                dt = p2['f'] - p1['f']
                if dt <= 0: continue
                dv = p2['speed'] - p1['speed']
                if p1['speed'] > 0.1:
                    decel = -dv / dt
                    all_data.append({
                        'scope': scope_title, 'type': 'decel',
                        'v_avg': (p1['speed'] + p2['speed']) / 2,
                        'decel': decel, 'mat': p1['props'].get('material')
                    })

        # Check collisions
        collisions = []
        for line in events_node['lines']:
            if 'collid' in line.lower():
                fm = re.match(r'Frame\s+(\d+)', line)
                f_col = int(fm.group(1))
                objs = re.findall(r'Object\s+(\d+)', line)
                if len(objs) == 2:
                    collisions.append({'f': f_col, 'oids': objs})
        for col in collisions:
            for oid in col['oids']:
                t_list = traj.get(oid, [])
                before = None
                after = None
                for p in t_list:
                    if p['f'] <= col['f']: before = p
                    if p['f'] >= col['f'] and after is None: after = p
                if before and after:
                    all_data.append({
                        'scope': scope_title, 'type': 'collision',
                        'f': col['f'], 'oid': oid, 'mat': before['props'].get('material'),
                        'v_before': before['speed'], 'v_after': after['speed'],
                        'vx_b': before['vx'], 'vy_b': before['vy'],
                        'vx_a': after['vx'], 'vy_a': after['vy']
                    })

    print("Entry velocities by material/shape:")
    entries = [d for d in all_data if d['type'] == 'entry']
    for e in entries[:20]:
        print(f"  {e['mat']} {e['shape']}: v=({e['vx']:.2f}, {e['vy']:.2f}) speed={e['speed']:.2f}")

    print("\nDeceleration by material:")
    decels = [d for d in all_data if d['type'] == 'decel']
    decels_by_mat = defaultdict(list)
    for d in decels:
        decels_by_mat[d['mat']].append(d['decel'] / d['v_avg']) # coeff of friction if proportional
    for mat, coeffs in decels_by_mat.items():
        if coeffs:
            print(f"  {mat}: avg coeff={np.mean(coeffs):.4f} std={np.std(coeffs):.4f} n={len(coeffs)}")

    print("\nCollision speed changes:")
    cols = [d for d in all_data if d['type'] == 'collision']
    for c in cols[:10]:
        print(f"  {c['scope']} {c['oid']} ({c['mat']}): v_b={c['v_before']:.2f} -> v_a={c['v_after']:.2f} ratio={c['v_after']/c['v_before']:.2f}")

