import math
import re
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if start is None: start = 0.0
    if horizon is None: horizon = recorded_end(doc, scope)
    if horizon is None: return []

    start = int(start)
    horizon = int(horizon)

    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)
    motion_node = None
    objects_node = None
    for n in children_nodes:
        if 'Motion log' in n['title']: motion_node = n
        if 'Objects' in n['title']: objects_node = n

    traj = defaultdict(list)
    if motion_node:
        for _, row in table_rows(motion_node):
            parts = row['object'].split()
            oid = parts[0]
            traj[oid].append({
                'f': int(row['frame']), 'x': float(row['x']), 'y': float(row['y']),
                'vx': float(row['vx']), 'vy': float(row['vy'])
            })
    for oid in traj:
        traj[oid].sort(key=lambda r: r['f'])

    obj_props = {}
    if objects_node:
        for line in objects_node['lines']:
            m = re.match(r'Object\s+(\d+):\s+\w+\s+(\w+)\s+(\w+)', line)
            if m:
                obj_props[m.group(1)] = {'material': m.group(2), 'shape': m.group(3)}

    obj_entry = {}
    for inp in inputs:
        for oid in inp['entities']:
            obj_entry[oid] = int(inp['time'])

    active_oids = sorted(obj_entry.keys())

    def get_state_at(oid, f):
        t_list = traj.get(oid, [])
        if not t_list: return None
        for r in t_list:
            if r['f'] == f: return {**r}
        lower = None
        upper = None
        for r in t_list:
            if r['f'] <= f: lower = r
            if r['f'] >= f and upper is None: upper = r
        if lower and upper and lower['f'] != upper['f']:
            t = (f - lower['f']) / (upper['f'] - lower['f'])
            return {
                'x': lower['x'] + t*(upper['x']-lower['x']),
                'y': lower['y'] + t*(upper['y']-lower['y']),
                'vx': lower['vx'] + t*(upper['vx']-lower['vx']),
                'vy': lower['vy'] + t*(upper['vy']-lower['vy'])
            }
        return {**lower} if lower else ({**upper} if upper else None)

    state = {}
    for oid in active_oids:
        if obj_entry[oid] > start: continue
        s = get_state_at(oid, start)
        if s: state[oid] = s

    outcomes = []
    FRICTION = 0.978
    COLLISION_THRESH = 0.45
    COR = 0.5

    def get_mass(oid):
        p = obj_props.get(oid, {})
        mat = p.get('material', 'metal')
        shp = p.get('shape', 'cube')
        m = 1.0 if mat == 'metal' else 0.5
        sm = {'cube': 1.0, 'cylinder': 0.75, 'sphere': 0.5}
        return m * sm.get(shp, 1.0)

    for t in range(start, horizon + 1):
        for inp in inputs:
            if int(inp['time']) == t:
                for oid in inp['entities']:
                    if oid not in state:
                        s = get_state_at(oid, t)
                        state[oid] = s or {'x':0.0, 'y':0.0, 'vx':0.0, 'vy':0.0}

        for oid in list(state.keys()):
            s = state[oid]
            s['x'] += s['vx']
            s['y'] += s['vy']
            s['vx'] *= FRICTION
            s['vy'] *= FRICTION

        colliding = set()
        for i, oid1 in enumerate(state):
            for oid2 in list(state.keys())[i+1:]:
                if (oid1, oid2) in colliding: continue
                s1, s2 = state[oid1], state[oid2]
                dx, dy = s1['x']-s2['x'], s1['y']-s2['y']
                dist = math.hypot(dx, dy)
                if dist < COLLISION_THRESH:
                    outcomes.append({'time': float(t), 'kind': 'collision', 'entities': [oid1, oid2], 'value': None})
                    colliding.add((oid1, oid2))
                    if dist > 1e-5:
                        nx, ny = dx/dist, dy/dist
                        dvx, dvy = s1['vx']-s2['vx'], s1['vy']-s2['vy']
                        dvn = dvx*nx + dvy*ny
                        if dvn < 0:
                            m1, m2 = get_mass(oid1), get_mass(oid2)
                            j = -(1+COR)*dvn / (1/m1 + 1/m2)
                            s1['vx'] += j*nx/m1; s1['vy'] += j*ny/m1
                            s2['vx'] -= j*nx/m2; s2['vy'] -= j*ny/m2
                            sep = (COLLISION_THRESH - dist)/2 + 0.01
                            s1['x'] += nx*sep; s1['y'] += ny*sep
                            s2['x'] -= nx*sep; s2['y'] -= ny*sep
    return outcomes

