import math
import numpy as np
from collections import defaultdict

def inputs_func(doc, scope):
    return inputs(doc, scope)

def test_sim(doc, scope, friction=0.978, thresh=1.0, cor=0.5, exit_b=4.0):
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)
    motion_node = None
    events_node = None
    objects_node = None
    for n in children_nodes:
        if 'Motion log' in n['title']: motion_node = n
        if 'Events' in n['title']: events_node = n
        if 'Objects' in n['title']: objects_node = n

    # Get actual outcomes
    actual = []
    if events_node:
        for idx, line in enumerate(events_node['lines']):
            fm = re.match(r'Frame\s+(\d+)', line)
            if not fm: continue
            f = int(fm.group(1))
            if 'collid' in line.lower():
                objs = re.findall(r'Object\s+(\d+)', line)
                actual.append({'time': float(f), 'kind': 'collision', 'entities': sorted(objs)})
            if any(kw in line.lower() for kw in ['leaves the', 'exits the', 'no longer']):
                objs = re.findall(r'Object\s+(\d+)', line)
                if objs:
                    actual.append({'time': float(f), 'kind': 'exit', 'entities': sorted(objs)})

    # Inputs
    inputs_list = inputs_func(doc, scope)
    obj_entry = {}
    for inp in inputs_list:
        for oid in inp['entities']:
            obj_entry[oid] = int(inp['time'])

    # Trajectory from motion log
    traj = defaultdict(list)
    if motion_node:
        for _, row in table_rows(motion_node):
            parts = row['object'].split()
            oid = parts[0]
            traj[oid].append({
                'f': int(row['frame']), 'x': float(row['x']), 'y': float(row['y']),
                'vx': float(row['vx']), 'vy': float(row['vy'])
            })
    for oid in traj:
        traj[oid].sort(key=lambda r: r['f'])

    start = 0.0
    horizon = recorded_end(doc, scope)

    # Initialize state at start
    state = {}
    for oid in obj_entry:
        if obj_entry[oid] > start: continue
        t_list = traj.get(oid, [])
        if not t_list: continue
        # Interpolate to start
        lower = None
        upper = None
        for r in t_list:
            if r['f'] <= start: lower = r
            if r['f'] >= start and upper is None: upper = r
        if lower and upper and lower['f'] != upper['f']:
            t_frac = (start - lower['f']) / (upper['f'] - lower['f'])
            state[oid] = {
                'x': lower['x'] + t_frac*(upper['x']-lower['x']),
                'y': lower['y'] + t_frac*(upper['y']-lower['y']),
                'vx': lower['vx'] + t_frac*(upper['vx']-lower['vx']),
                'vy': lower['vy'] + t_frac*(upper['vy']-lower['vy'])
            }
        else:
            state[oid] = {**lower} if lower else {**upper}

    pred = []
    t = int(start)
    while t <= int(horizon):
        # Add entering objects
        for inp in inputs_list:
            if int(inp['time']) == t:
                for oid in inp['entities']:
                    if oid not in state:
                        t_list = traj.get(oid, [])
                        if t_list:
                            p = next((r for r in t_list if r['f'] == t), None)
                            if p: state[oid] = {**p}

        # Update positions and friction
        for oid in state:
            s = state[oid]
            s['x'] += s['vx']
            s['y'] += s['vy']
            s['vx'] *= friction
            s['vy'] *= friction

        # Collisions
        colliding = set()
        for i, o1 in enumerate(list(state.keys())):
            for o2 in list(state.keys())[i+1:]:
                s1, s2 = state[o1], state[o2]
                dx, dy = s1['x']-s2['x'], s1['y']-s2['y']
                dist = math.hypot(dx, dy)
                if dist < thresh:
                    pred.append({'time': float(t), 'kind': 'collision', 'entities': sorted([o1, o2])})
                    colliding.add((o1, o2))
                    if dist > 1e-5:
                        nx, ny = dx/dist, dy/dist
                        dvx, dvy = s1['vx']-s2['vx'], s1['vy']-s2['vy']
                        dvn = dvx*nx + dvy*ny
                        if dvn < 0:
                            j = -(1+cor)*dvn / 2.0
                            s1['vx'] += j*nx; s1['vy'] += j*ny
                            s2['vx'] -= j*nx; s2['vy'] -= j*ny
                            sep = (thresh - dist)/2 + 0.01
                            s1['x'] += nx*sep; s1['y'] += ny*sep
                            s2['x'] -= nx*sep; s2['y'] -= ny*sep

        # Exits
        exited = []
        for oid, s in state.items():
            if abs(s['x']) > exit_b or abs(s['y']) > exit_b:
                pred.append({'time': float(t), 'kind': 'exit', 'entities': [oid]})
                exited.append(oid)
        for oid in exited:
            del state[oid]

        t += 1

    # Compare
    def match(a, p):
        if a['kind'] != p['kind']: return False
        if abs(a['time'] - p['time']) > 1: return False
        if set(a['entities']) != set(p['entities']): return False
        return True

    matched = 0
    for a in actual:
        for p in pred:
            if match(a, p):
                matched += 1
                break
    tp = matched
    fp = len(pred) - tp
    fn = len(actual) - tp
    prec = tp / (tp + fp) if (tp + fp) > 0 else 0
    rec = tp / (tp + fn) if (tp + fn) > 0 else 0
    f1 = 2*prec*rec / (prec+rec) if (prec+rec) > 0 else 0
    print(f"{scope}: F1={f1:.2f} Actual={len(actual)} Pred={len(pred)} TP={tp} FP={fp} FN={fn}")
    if f1 < 0.8:
        print(f"  Actual: {actual}")
        print(f"  Pred: {pred}")
    return pred, actual, f1

