    objects_node = None
    for n in child_nodes:
        if 'Motion log' in n['title']: motion_node = n
        if 'Objects' in n['title']: objects_node = n

    obj_props = {}
    if objects_node:
        for line in objects_node['lines']:
            m = re.match(r'Object\s+(\d+):\s+\w+\s+(\w+)\s+(\w+)', line)
            if m:
                obj_props[m.group(1)] = {'material': m.group(2), 'shape': m.group(3)}

    traj = defaultdict(list)
    if motion_node:
        for _, row in table_rows(motion_node):
            parts = row['object'].split()
            oid = parts[0]
            traj[oid].append({
                'f': int(row['frame']),
                'x': float(row['x']), 'y': float(row['y']),
                'vx': float(row['vx']), 'vy': float(row['vy'])
            })
    for oid in traj:
        traj[oid].sort(key=lambda r: r['f'])

    if horizon is None:
        horizon = recorded_end(doc, scope)
    if horizon is None:
        return []
    if start is None:
        start = 0.0

    entry_times = {}
    for inp in inputs:
        for oid in inp['entities']:
            entry_times[oid] = float(inp['time'])

    def get_state_at(t):
        res = {}
        for oid, et in entry_times.items():
            if et > t: continue
            t_list = traj.get(oid, [])
            if not t_list:
                res[oid] = {'x': 0.0, 'y': 0.0, 'vx': 0.0, 'vy': 0.0}
                continue
            lower = None
            upper = None
            for r in t_list:
                if r['f'] <= t: lower = r
                if r['f'] >= t and upper is None: upper = r
            if lower and upper and lower['f'] != upper['f']:
                frac = (t - lower['f']) / (upper['f'] - lower['f'])
                res[oid] = {
                    'x': lower['x'] + frac * (upper['x'] - lower['x']),
                    'y': lower['y'] + frac * (upper['y'] - lower['y']),
                    'vx': lower['vx'] + frac * (upper['vx'] - lower['vx']),
                    'vy': lower['vy'] + frac * (upper['vy'] - lower['vy'])
                }
            elif lower:
                res[oid] = {**lower}
            elif upper:
                res[oid] = {**upper}
        return res

    state = get_state_at(start)
    outcomes = []

    FRICTION = 0.978
    COLLISION_RADIUS = 0.45
    RESTITUTION = 0.5
    EXIT_BOUND = 4.0

    def get_mass(oid):
        p = obj_props.get(oid, {})
        return 1.0 if p.get('material') == 'metal' else 0.5

    t = int(start)
    while t <= int(horizon):
        for inp in inputs:
            if float(inp['time']) == t:
                for oid in inp['entities']:
                    if oid not in state:
                        t_list = traj.get(oid, [])
                        rec = next((r for r in t_list if r['f'] == t), None)
                        state[oid] = {**rec} if rec else {'x': 0.0, 'y': 0.0, 'vx': 0.0, 'vy': 0.0}

        for oid in list(state.keys()):
            s = state[oid]
            s['x'] += s['vx']
            s['y'] += s['vy']
            s['vx'] *= FRICTION
            s['vy'] *= FRICTION

        colliding_pairs = set()
        oids = list(state.keys())
        for i in range(len(oids)):
            for j in range(i+1, len(oids)):
                o1, o2 = oids[i], oids[j]
                s1, s2 = state[o1], state[o2]
                dx = s1['x'] - s2['x']
                dy = s1['y'] - s2['y']
                dist = math.hypot(dx, dy)

                if dist < COLLISION_RADIUS and dist > 1e-5:
                    colliding_pairs.add((o1, o2))
                    outcomes.append({
                        'time': float(t),
                        'kind': 'collision',
                        'entities': sorted([o1, o2]),
                        'value': None,
                        'src': []
                    })

                    nx = dx / dist
                    ny = dy / dist
                    dvx = s1['vx'] - s2['vx']
                    dvy = s1['vy'] - s2['vy']
                    dvn = dvx * nx + dvy * ny

                    if dvn < 0:
                        m1 = get_mass(o1)
                        m2 = get_mass(o2)
                        j = -(1 + RESTITUTION) * dvn / (1/m1 + 1/m2)
                        s1['vx'] += j * nx / m1
                        s1['vy'] += j * ny / m1
                        s2['vx'] -= j * nx / m2
                        s2['vy'] -= j * ny / m2

                        overlap = COLLISION_RADIUS - dist
                        sep = overlap / 2 + 0.01
                        s1['x'] += nx * sep
                        s1['y'] += ny * sep
                        s2['x'] -= nx * sep
                        s2['y'] -= ny * sep

        exited = []
        for oid, s in state.items():
            if abs(s['x']) > EXIT_BOUND or abs(s['y']) > EXIT_BOUND:
                outcomes.append({
                    'time': float(t),
                    'kind': 'exit',
                    'entities': [oid],
                    'value': None,
                    'src': []
                })
                exited.append(oid)
        for oid in exited:
            del state[oid]

        t += 1

    return outcomes

