    state = {}
    for oid, et in entry_times.items():
        if et > t_start: continue
        s = get_state_at(oid, t_start)
        if s is not None:
            state[oid] = s

    outcomes = []
    FRICTION = 0.978
    COLLISION_RADIUS = 0.5
    RESTITUTION = 0.5
    EXIT_BOUND = 2.5
    STATIONARY = params.get('stationary_speed_threshold', 0.1)

    def get_mass(oid):
        p = obj_props.get(oid, {})
        return 1.0 if p.get('material') == 'metal' else 0.5

    t = t_start
