            s = state[oid]
            s['vx'] *= FRICTION
            s['vy'] *= FRICTION
            sp = math.hypot(s['vx'], s['vy'])
            if sp < STATIONARY:
                s['vx'] = 0.0
                s['vy'] = 0.0
            s['x'] += s['vx']
            s['y'] += s['vy']

        oids = list(state.keys())
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                o1, o2 = oids[i], oids[j]
                s1, s2 = state[o1], state[o2]
                dx = s1['x'] - s2['x']
                dy = s1['y'] - s2['y']
                dist = math.hypot(dx, dy)

                if dist < COLLISION_RADIUS and dist > 1e-5:
                    outcomes.append({
                        'time': float(t), 'kind': 'collision',
                        'entities': sorted([o1, o2]), 'value': None, 'src': []
                    })
                    nx, ny = dx / dist, dy / dist
                    dvx, dvy = s1['vx'] - s2['vx'], s1['vy'] - s2['vy']
                    dvn = dvx * nx + dvy * ny
                    if dvn < 0:
                        m1, m2 = get_mass(o1), get_mass(o2)
                        j_imp = -(1 + RESTITUTION) * dvn / (1/m1 + 1/m2)
                        s1['vx'] += j_imp * nx / m1
                        s1['vy'] += j_imp * ny / m1
                        s2['vx'] -= j_imp * nx / m2
                        s2['vy'] -= j_imp * ny / m2
                        sep = (COLLISION_RADIUS - dist) / 2 + 0.01
                        s1['x'] += nx * sep; s1['y'] += ny * sep
                        s2['x'] -= nx * sep; s2['y'] -= ny * sep

        exited = []
        for oid, s in state.items():
            if abs(s['x']) > EXIT_BOUND or abs(s['y']) > EXIT_BOUND:
                outcomes.append({
                    'time': float(t), 'kind': 'exit',
                    'entities': [oid], 'value': None, 'src': []
                })
                exited.append(oid)
        for oid in exited:
            del state[oid]

        t += 1

    return outcomes

