import re
import math

def analyze_collisions_and_motion():
    scopes = ["Video 14735", "Video 10251", "Video 10289", "Video 10482", "Video 11031", "Video 11203", "Video 11316", "Video 11812", "Video 11833"]

    collisions = []
    motion_samples = []

    for scope in scopes:
        scope_node = node_by_title(doc, scope)
        children_list = children(doc, scope_node)
        events_node = None
        motion_node = None
        objects_node = None
        for n in children_list:
            if 'Events' in n['title'] and n['kind'] == 'list':
                events_node = n
            if 'Motion log' in n['title'] and n['kind'] == 'table':
                motion_node = n
            if 'Objects' in n['title'] and n['kind'] == 'list':
                objects_node = n

        if not events_node or not motion_node or not objects_node:
            continue

        obj_props = {}
        for line in objects_node['lines']:
            m = re.match(r'Object\s+(\d+):\s+(\w+)\s+(\w+)\s+(\w+)', line)
            if m:
                obj_props[m.group(1)] = {'color': m.group(2), 'material': m.group(3), 'shape': m.group(4)}

        motion_data = {}
        for _, row in table_rows(motion_node):
            obj_str = row['object']
            oid = obj_str.split()[0]
            frame = int(row['frame'])
            speed = float(row['speed'])
            if oid not in motion_data:
                motion_data[oid] = {}
            motion_data[oid][frame] = {
                'vx': float(row['vx']), 'vy': float(row['vy']), 'speed': speed
            }

        # Collect motion samples for friction analysis
        for oid, frames_dict in motion_data.items():
            frames_sorted = sorted(frames_dict.keys())
            for i in range(len(frames_sorted)-1):
                f1, f2 = frames_sorted[i], frames_sorted[i+1]
                s1 = frames_dict[f1]['speed']
                s2 = frames_dict[f2]['speed']
                dt = f2 - f1
                if dt > 0:
                    decel = (s1 - s2) / dt
                    motion_samples.append({
                        'scope': scope, 'oid': oid, 'material': obj_props.get(oid, {}).get('material'),
                        'shape': obj_props.get(oid, {}).get('shape'),
                        't1': f1, 't2': f2, 's1': s1, 's2': s2, 'decel': decel, 'dt': dt
                    })

        # Collisions
        for idx, line in enumerate(events_node['lines']):
            if 'collid' in line.lower():
                fm = re.match(r'Frame\s+(\d+)', line)
                obj_ids = re.findall(r'Object\s+(\d+)', line)
                if fm and len(obj_ids) == 2:
                    t = int(fm.group(1))
                    o1, o2 = obj_ids[0], obj_ids[1]

                    def get_closest(oid, t, mode='pre'):
                        if oid not in motion_data: return None
                        frames = sorted(motion_data[oid].keys())
                        if mode == 'pre':
                            best = max((f for f in frames if f <= t), default=None)
                        else:
                            best = min((f for f in frames if f >= t), default=None)
                        if best is None: return None
                        return motion_data[oid][best]

                    pre1 = get_closest(o1, t, 'pre')
                    pre2 = get_closest(o2, t, 'pre')
                    post1 = get_closest(o1, t, 'post')
                    post2 = get_closest(o2, t, 'post')

                    if pre1 and pre2 and post1 and post2:
                        collisions.append({
                            'scope': scope, 'frame': t, 'o1': o1, 'o2': o2,
                            'p1': obj_props.get(o1, {}), 'p2': obj_props.get(o2, {}),
                            'v1_pre': (pre1['vx'], pre1['vy']), 'v2_pre': (pre2['vx'], pre2['vy']),
                            'v1_post': (post1['vx'], post1['vy']), 'v2_post': (post2['vx'], post2['vy'])
                        })

    print("=== FRICTION/DECCELERATION SAMPLES (deceleration per frame) ===")
    # Group by material
    from collections import defaultdict
    mat_decel = defaultdict(list)
    for s in motion_samples:
        mat_decel[s['material']].append(s['decel'])
    for mat, decels in mat_decel.items():
        avg = sum(decels)/len(decels) if decels else 0
        print(f"{mat}: avg decel/frame = {avg:.4f}, count={len(decels)}")

    print("\n=== COLLISION MOMENTUM ANALYSIS ===")
    for c in collisions[:10]:
        v1p, v2p = c['v1_pre'], c['v2_pre']
        v1post, v2post = c['v1_post'], c['v2_post']
        dv1 = (v1post[0]-v1p[0], v1post[1]-v1p[1])
        dv2 = (v2post[0]-v2p[0], v2post[1]-v2p[1])
        # Check if velocities are just interpolated or if collision happens exactly at frame
        # If collision is exactly at frame, dv should reflect impact.
        # Sometimes post frame is same as pre frame if recorded at collision frame.
        # Let's compute impulse direction and magnitude ratio
        mag_dv1 = math.sqrt(dv1[0]**2 + dv1[1]**2)
        mag_dv2 = math.sqrt(dv2[0]**2 + dv2[1]**2)
        mat1, mat2 = c['p1'].get('material'), c['p2'].get('material')
        print(f"{c['scope']} F{c['frame']} {mat1}({c['o1']}) vs {mat2}({c['o2']}) | dv1_mag={mag_dv1:.3f}, dv2_mag={mag_dv2:.3f} | ratio m2/m1 ~ {mag_dv1/mag_dv2:.2f} if elastic")

