import re
import math
from collections import defaultdict

def analyze():
    scopes = ["Video 14735", "Video 10251", "Video 10289", "Video 10482", "Video 11031", "Video 11203", "Video 11316", "Video 11812", "Video 11833", "Video 12454", "Video 12640", "Video 13246", "Video 13505", "Video 13508", "Video 13663", "Video 13706", "Video 14163", "Video 14248", "Video 14308", "Video 14480"]

    all_motion = []
    all_collisions = []
    all_events = []

    for scope in scopes:
        scope_node = node_by_title(doc, scope)
        children_list = children(doc, scope_node)
        events_node = None
        motion_node = None
        objects_node = None
        for n in children_list:
            if 'Events' in n['title'] and n['kind'] == 'list':
                events_node = n
            if 'Motion log' in n['title'] and n['kind'] == 'table':
                motion_node = n
            if 'Objects' in n['title'] and n['kind'] == 'list':
                objects_node = n

        if not motion_node or not objects_node: continue

        obj_props = {}
        for line in objects_node['lines']:
            m = re.match(r'Object\s+(\d+):\s+(\w+)\s+(\w+)\s+(\w+)', line)
            if m:
                obj_props[m.group(1)] = {'material': m.group(3), 'shape': m.group(4)}

        for _, row in table_rows(motion_node):
            obj_str = row['object']
            oid = obj_str.split()[0]
            all_motion.append({
                'scope': scope, 'frame': int(row['frame']), 'oid': oid,
                'vx': float(row['vx']), 'vy': float(row['vy']),
                'mat': obj_props.get(oid, {}).get('material')
            })

        if events_node:
            for idx, line in enumerate(events_node['lines']):
                m = re.match(r'Frame\s+(\d+):', line)
                if m:
                    t = int(m.group(1))
                    obj_ids = re.findall(r'Object\s+(\d+)', line)
                    kind = 'other'
                    if 'collid' in line.lower(): kind = 'collision'
                    if 'enters' in line.lower() or 'begins' in line.lower(): kind = 'entry'
                    if 'exits' in line.lower() or 'leaves' in line.lower() or 'no longer' in line.lower(): kind = 'exit'
                    all_events.append({'scope': scope, 'frame': t, 'kind': kind, 'objs': obj_ids, 'line': line})
                    if kind == 'collision':
                        all_collisions.append({'scope': scope, 'frame': t, 'o1': obj_ids[0], 'o2': obj_ids[1]})

    motion_by_scope = defaultdict(list)
    for m in all_motion:
        motion_by_scope[m['scope']].append(m)

    decels = defaultdict(list)
    coll_frames = defaultdict(set)
    for c in all_collisions:
        coll_frames[c['scope']].add(c['frame'])

    for scope, ms in motion_by_scope.items():
        ms_by_oid = defaultdict(list)
        for m in ms:
            ms_by_oid[m['oid']].append(m)

        for oid, samples in ms_by_oid.items():
            samples.sort(key=lambda x: x['frame'])
            for i in range(len(samples)-1):
                s1, s2 = samples[i], samples[i+1]
                dt = s2['frame'] - s1['frame']
                if dt == 0: continue
                # Skip if crossing a collision frame
                if any(cf > s1['frame'] and cf <= s2['frame'] for cf in coll_frames[scope]):
                    continue
                dv = math.sqrt((s2['vx']-s1['vx'])**2 + (s2['vy']-s1['vy'])**2)
                decel = dv / dt
                if s1['mat']:
                    decels[s1['mat']].append(decel)

    print("=== Deceleration by material (avg per frame) ===")
    for mat, dcs in decels.items():
        avg = sum(dcs)/len(dcs)
        print(f"{mat}: avg={avg:.4f}, n={len(dcs)}")

    print("\n=== Collision velocity changes ===")
    for c in all_collisions[:15]:
        scope = c['scope']
        t = c['frame']
        o1, o2 = c['o1'], c['o2']
        ms = [m for m in motion_by_scope[scope] if m['oid'] in [o1, o2]]
        by_oid = defaultdict(list)
        for m in ms:
            by_oid[m['oid']].append(m)

        def get_v(oid, target_t, mode='pre'):
            samples = by_oid[oid]
            if not samples: return None
            if mode == 'pre':
                best = max(samples, key=lambda s: s['frame']) if all(s['frame'] <= target_t for s in samples) else max((s for s in samples if s['frame'] <= target_t), default=None)
                if best is None: best = max(samples, key=lambda s: s['frame'])
            else:
                best = min(samples, key=lambda s: s['frame']) if all(s['frame'] >= target_t for s in samples) else min((s for s in samples if s['frame'] >= target_t), default=None)
                if best is None: best = min(samples, key=lambda s: s['frame'])
            return best['vx'], best['vy']

        v1_pre = get_v(o1, t, 'pre')
        v2_pre = get_v(o2, t, 'pre')
        v1_post = get_v(o1, t, 'post')
        v2_post = get_v(o2, t, 'post')

        if v1_pre and v2_pre and v1_post and v2_post:
            print(f"{scope} F{t} {o1} vs {o2}: v1_pre={v1_pre}, v2_pre={v2_pre} -> v1_post={v1_post}, v2_post={v2_post}")

