        if events_node:
            for line in events_node['lines']:
                if 'collid' in line.lower():
                    m = re.match(r'Frame\s+(\d+)', line)
                    if m: coll_frames.add(int(m.group(1)))

        data = defaultdict(list)
        for _, row in table_rows(motion_node):
            oid = row['object'].split()[0]
            data[oid].append({
                'f': int(row['frame']),
                'v': math.sqrt(float(row['vx'])**2 + float(row['vy'])**2)
            })

        for oid, samples in data.items():
            samples.sort(key=lambda s: s['f'])
            for i in range(len(samples)-1):
                s1, s2 = samples[i], samples[i+1]
                dt = s2['f'] - s1['f']
                if dt == 0: continue
                if any(cf > s1['f'] and cf <= s2['f'] for cf in coll_frames): continue
                if s1['v'] > 0.1:
                    friction_samples.append((math.log(s2['v']/s1['v']) / dt, dt))

    avg_friction = sum(s[0] for s in friction_samples) / len(friction_samples) if friction_samples else 0
    print(f"Avg log friction per frame: {avg_friction:.5f} => factor per frame: {math.exp(avg_friction):.5f}")

    # Collision analysis
    print("\n=== Collision Velocity Changes ===")
    for scope in scopes[:5]:
