                'vx': float(row['vx']), 'vy': float(row['vy'])
            })
        for oid in data: data[oid].sort(key=lambda s: s['f'])

        for line in events_node['lines']:
            if 'collid' in line.lower():
                m = re.match(r'Frame\s+(\d+)', line)
                objs = re.findall(r'Object\s+(\d+)', line)
                if not m or len(objs) != 2: continue
                t = int(m.group(1))
                o1, o2 = objs[0], objs[1]

                def get_closest(oid, t, mode='pre'):
                    arr = data[oid]
                    if not arr: return None
                    if mode == 'pre':
                        best = max((s for s in arr if s['f'] <= t), default=arr[-1])
                    else:
                        best = min((s for s in arr if s['f'] >= t), default=arr[0])
                    return best

                s1_pre = get_closest(o1, t, 'pre')
                s2_pre = get_closest(o2, t, 'pre')
                s1_post = get_closest(o1, t, 'post')
                s2_post = get_closest(o2, t, 'post')

                if s1_pre and s2_pre and s1_post and s2_post:
                    print(f"{scope} F{t} {o1} vs {o2}:")
                    print(f"  Pre: {o1}({s1_pre['vx']:.2f},{s1_pre['vy']:.2f}) {o2}({s2_pre['vx']:.2f},{s2_pre['vy']:.2f})")
                    print(f"  Post: {o1}({s1_post['vx']:.2f},{s1_post['vy']:.2f}) {o2}({s2_post['vx']:.2f},{s2_post['vy']:.2f})")

