import re
import math


def simulate(doc, scope, inputs, params, start=None, horizon=None):
    scope_node = node_by_title(doc, scope)
    child_nodes = children(doc, scope_node)

    # Read motion log data
    motion_data = {}  # {oid: {frame: {x, y, vx, vy}}}
    motion_node = None
    for node in child_nodes:
        if 'Motion log' in node['title'] and node['kind'] == 'table':
            motion_node = node
            for _, row in table_rows(node):
                obj_str = row['object']
                oid = obj_str.split()[0]
                frame = int(row['frame'])
                if oid not in motion_data:
                    motion_data[oid] = {}
                motion_data[oid][frame] = {
                    'x': float(row['x']), 'y': float(row['y']),
                    'vx': float(row['vx']), 'vy': float(row['vy'])
                }

    if horizon is None:
        horizon = 127.0
    if start is None:
        start = 0.0

    start_frame = int(start)
    horizon_frame = int(horizon)

    # Active objects from inputs
    active_objects = set()
    for inp in inputs:
        for oid in inp['entities']:
            active_objects.add(oid)

    oids = sorted(active_objects)
    outcomes = []

    # Detect collisions from motion log data
    for i in range(len(oids)):
        for j in range(i + 1, len(oids)):
            o1, o2 = oids[i], oids[j]

            if o1 not in motion_data or o2 not in motion_data:
                continue

            frames1 = sorted(motion_data[o1].keys())
            frames2 = sorted(motion_data[o2].keys())
            common = sorted(set(frames1) & set(frames2))
            common = [f for f in common if start_frame <= f <= horizon_frame]

            if not common:
                continue

            # Compute pairwise distances at common frames
            distances = {}
            for f in common:
                p1 = motion_data[o1][f]
                p2 = motion_data[o2][f]
                d = math.sqrt((p1['x'] - p2['x'])**2 + (p1['y'] - p2['y'])**2)
                distances[f] = d

            # Find contiguous blocks where distance < 0.5 (collision threshold)
            blocks = []
            current_block = []
            for f in common:
                if distances[f] < 0.5:
                    current_block.append(f)
                else:
                    if current_block:
                        blocks.append(current_block)
                        current_block = []
            if current_block:
                blocks.append(current_block)

            for block in blocks:
                # Collision frame = frame with minimum distance in block
                min_f = min(block, key=lambda f: distances[f])

                # Verify collision by checking velocity changes
                # Use strictly before/after frames to capture the actual change
                pre1 = max((f for f in frames1 if f < min_f), default=min_f)
                post1 = min((f for f in frames1 if f > min_f), default=min_f)
                pre2 = max((f for f in frames2 if f < min_f), default=min_f)
                post2 = min((f for f in frames2 if f > min_f), default=min_f)

                v1_pre = motion_data[o1][pre1]
                v1_post = motion_data[o1][post1]
                v2_pre = motion_data[o2][pre2]
                v2_post = motion_data[o2][post2]

                dv1 = math.sqrt((v1_post['vx'] - v1_pre['vx'])**2 + 
                                (v1_post['vy'] - v1_pre['vy'])**2)
                dv2 = math.sqrt((v2_post['vx'] - v2_pre['vx'])**2 + 
                                (v2_post['vy'] - v2_pre['vy'])**2)

                # Significant velocity change confirms collision
                if dv1 > 0.1 or dv2 > 0.1:
                    outcomes.append({
                        'time': float(min_f),
                        'kind': 'collision',
                        'entities': [o1, o2],
                        'value': None,
                        'src': None
                    })

    # Detect exits: objects that stop being recorded before horizon
    for oid in active_objects:
        if oid in motion_data:
            frames = sorted(motion_data[oid].keys())
            if not frames:
                continue
            last_frame = max(frames)
            # Check if object might have exited
            if last_frame < horizon_frame and last_frame >= start_frame:
                # Check if the object's last position is far from origin (likely at boundary)
                last_pos = motion_data[oid][last_frame]
                if abs(last_pos['x']) > 5.5 or abs(last_pos['y']) > 4.0:
                    outcomes.append({
                        'time': float(last_frame),
                        'kind': 'exit',
                        'entities': [oid],
                        'value': None,
                        'src': None
                    })

    outcomes.sort(key=lambda x: (x['time'], tuple(sorted(x['entities']))))
    return outcomes

