import re
import math
from collections import defaultdict
from copy import deepcopy


def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_speed_threshold", 0.1)

    # Get motion log from document
    scope_node = node_by_title(doc, scope)
    child_nodes = children(doc, scope_node)
    motion_node = None
    for node in child_nodes:
        if 'Motion log' in node['title'] and node['kind'] == 'table':
            motion_node = node

    # Read motion log data: {oid: {frame: {x, y, vx, vy}}}
    raw_motion = defaultdict(dict)
    if motion_node:
        for _, row in table_rows(motion_node):
            obj_str = row['object']
            oid = obj_str.split()[0]
            frame = int(row['frame'])
            raw_motion[oid][frame] = {
                'x': float(row['x']), 'y': float(row['y']),
                'vx': float(row['vx']), 'vy': float(row['vy'])
            }

    # Determine start and horizon
    if horizon is None:
        horizon = 127.0
    if start is None:
        start = 0.0

    start_frame = int(start)
    horizon_frame = int(horizon)

    # Active objects from inputs only
    active_objects = set()
    entry_times = {}  # oid -> entry frame
    for inp in inputs:
        t = inp['time']
        if t >= start_frame:
            for oid in inp['entities']:
                active_objects.add(oid)
                if oid not in entry_times or t < entry_times[oid]:
                    entry_times[oid] = int(t)

    if not active_objects:
        return []

    # Friction parameters - estimated from data
    # Velocity decays by about 0.985 per frame on average
    friction_per_frame = 0.985

    # Collision distance threshold
    collision_dist = 0.45

    # Initialize object states at entry time from motion log
    # State: {oid: {x, y, vx, vy, active, exit_frame}}
    states = {}
    for oid in active_objects:
        entry_frame = entry_times[oid]
        motion = raw_motion.get(oid, {})

        # Find closest motion log frame to entry
        if motion:
            frames = sorted(motion.keys())
            # Prefer entry frame itself
            if entry_frame in motion:
                best_frame = entry_frame
            else:
                # Find closest frame >= entry
                after = [f for f in frames if f >= entry_frame]
                before = [f for f in frames if f <= entry_frame]
                if after and before:
                    d_after = after[0] - entry_frame
                    d_before = entry_frame - before[-1]
                    best_frame = after[0] if d_after <= d_before else before[-1]
                elif after:
                    best_frame = after[0]
                elif before:
                    best_frame = before[-1]
                else:
                    best_frame = frames[0]

            s = motion[best_frame]
            states[oid] = {
                'x': s['x'], 'y': s['y'],
                'vx': s['vx'], 'vy': s['vy'],
                'active': True, 'entered': entry_frame
            }
        else:
            # No motion data - can't track this object
            states[oid] = None

    # Filter out objects we can't track
    active_states = {oid: states[oid] for oid in active_objects if states[oid] is not None}

    outcomes = []
    processed_collisions = set()

    # Simulate frame by frame
    current_frame = start_frame
    while current_frame <= horizon_frame:
        active_list = sorted(active_states.keys())

        # Check for collisions between all pairs
        for i in range(len(active_list)):
            for j in range(i + 1, len(active_list)):
                o1, o2 = active_list[i], active_list[j]
                s1 = active_states[o1]
                s2 = active_states[o2]
                if not s1 or not s2 or not s1.get('active', False) or not s2.get('active', False):
                    continue

                dx = s1['x'] - s2['x']
                dy = s1['y'] - s2['y']
                dist = math.sqrt(dx * dx + dy * dy)

                if dist < collision_dist and dist > 0:
                    # Collision detected
                    key = (min(o1, o2), max(o1, o2), current_frame)
                    if key not in processed_collisions:
                        processed_collisions.add(key)
                        outcomes.append({
                            'time': float(current_frame),
                            'kind': 'collision',
                            'entities': [o1, o2],
                            'value': None,
                            'src': None
                        })

                        # Apply elastic collision (equal mass)
                        # Normal direction from o2 to o1
                        nx, ny = dx / dist, dy / dist

                        # Relative velocity along normal
                        dvx = s1['vx'] - s2['vx']
                        dvy = s1['vy'] - s2['vy']
                        rel_vn = dvx * nx + dvy * ny

                        # Only if approaching (relative velocity along normal is negative for o1)
                        # For equal mass elastic: velocities swap along normal
                        s1['vx'] -= rel_vn * nx
                        s1['vy'] -= rel_vn * ny
                        s2['vx'] += rel_vn * nx
                        s2['vy'] += rel_vn * ny

        # Check for exits (objects leaving the visible area)
        for oid in active_list:
            s = active_states[oid]
            if not s or not s.get('active', False):
                continue
            if abs(s['x']) > 5.8 or abs(s['y']) > 4.5:
                outcomes.append({
                    'time': float(current_frame),
                    'kind': 'exit',
                    'entities': [oid],
                    'value': None,
                    'src': None
                })
                s['active'] = False

        # Update positions and apply friction for all active objects
        for oid in active_list:
            s = active_states[oid]
            if not s or not s.get('active', False):
                continue
            # Apply friction
            s['vx'] *= friction_per_frame
            s['vy'] *= friction_per_frame
            # Update position
            s['x'] += s['vx']
            s['y'] += s['vy']

        current_frame += 1

    # Deduplicate collisions at same frame for same pair
    seen = set()
    deduped = []
    for o in sorted(outcomes, key=lambda x: (x['time'], tuple(sorted(x['entities'])))):
        key = (o['kind'], tuple(sorted(o['entities'])), o['time'])
        if key not in seen:
            seen.add(key)
            deduped.append(o)

    return deduped

