import re
import math
from collections import defaultdict


def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_speed_threshold", 0.1)

    # Get motion log from document
    scope_node = node_by_title(doc, scope)
    child_nodes = children(doc, scope_node)
    motion_node = None
    for node in child_nodes:
        if 'Motion log' in node['title'] and node['kind'] == 'table':
            motion_node = node

    # Parse motion log: oid -> {frame: {x, y, vx, vy}}
    motion_by_obj = defaultdict(dict)
    if motion_node:
        for _, row in table_rows(motion_node):
            obj_str = row['object']
            oid = obj_str.split()[0]
            frame = int(row['frame'])
            motion_by_obj[oid][frame] = {
                'x': float(row['x']), 'y': float(row['y']),
                'vx': float(row['vx']), 'vy': float(row['vy'])
            }

    # Determine time range
    if horizon is None:
        horizon = 127.0
    if start is None:
        start = 0.0

    start_frame = int(start)
    horizon_frame = int(horizon)

    # Active objects from inputs ONLY
    active_objects = set()
    obj_entry_frames = {}
    for inp in inputs:
        for oid in inp['entities']:
            active_objects.add(oid)
            if oid not in obj_entry_frames or inp['time'] < obj_entry_frames[oid]:
                obj_entry_frames[oid] = inp['time']

    if not active_objects:
        return []

    # Initialize state at start_frame for each active object
    # Use motion log data to reconstruct state
    states = {}
    for oid in active_objects:
        if oid not in motion_by_obj:
            # Object has no motion data - skip
            continue

        frames_dict = motion_by_obj[oid]
        all_frames = sorted(frames_dict.keys())

        # Only consider objects whose entry frame is before or at start
        if obj_entry_frames.get(oid, 0) > start:
            # Object hasn't entered yet - initialize with entry frame data if available
            entry_frame = int(obj_entry_frames[oid])
            if entry_frame in frames_dict:
                s = frames_dict[entry_frame]
                # Advance from entry to start
                dt = start_frame - entry_frame
                x = s['x'] + s['vx'] * dt
                y = s['y'] + s['vy'] * dt
                states[oid] = {'x': x, 'y': y, 'vx': s['vx'], 'vy': s['vy'], 'active': True}
            continue

        # Find best frame to initialize from
        # Prefer frame at or just before start_frame
        best_frame = None
        for f in all_frames:
            if f <= start_frame:
                best_frame = f
            elif best_frame is None:
                best_frame = f
                break

        if best_frame is None:
            best_frame = all_frames[0]

        s_init = frames_dict[best_frame]
        dt = start_frame - best_frame

        # Advance position by velocity * dt
        x = s_init['x'] + s_init['vx'] * dt
        y = s_init['y'] + s_init['vy'] * dt
        vx = s_init['vx']
        vy = s_init['vy']

        states[oid] = {'x': x, 'y': y, 'vx': vx, 'vy': vy, 'active': True}

    active_ids = sorted(states.keys())

    # Physics constants
    friction_per_frame = 0.985
    collision_dist = 0.45
    x_limit = 6.0
    y_limit = 5.0

    # Simulate frame by frame
    current_frame = start_frame
    outcomes = []
    seen_collisions = set()

    while current_frame <= horizon_frame:
        # 1. Collision detection (check current positions)
        for i in range(len(active_ids)):
            for j in range(i + 1, len(active_ids)):
                o1, o2 = active_ids[i], active_ids[j]
                s1, s2 = states[o1], states[o2]

                if not s1['active'] or not s2['active']:
                    continue

                dx = s1['x'] - s2['x']
                dy = s1['y'] - s2['y']
                dist = math.sqrt(dx*dx + dy*dy)

                if dist < collision_dist:
                    key = (min(o1, o2), max(o1, o2), current_frame)
                    if key not in seen_collisions:
                        seen_collisions.add(key)
                        outcomes.append({
                            'time': float(current_frame),
                            'kind': 'collision',
                            'entities': [o1, o2],
                            'value': None,
                            'src': None
                        })

                        # Elastic collision response (equal mass)
                        if dist > 0.001:
                            nx, ny = dx/dist, dy/dist
                            dvx = s1['vx'] - s2['vx']
                            dvy = s1['vy'] - s2['vy']
                            rel_vn = dvx*nx + dvy*ny

                            # Only swap if approaching
                            if rel_vn < 0:
                                s1['vx'] -= rel_vn * nx
                                s1['vy'] -= rel_vn * ny
                                s2['vx'] += rel_vn * nx
                                s2['vy'] += rel_vn * ny

        # 2. Check for exits
        exiting = []
        for oid in active_ids:
            s = states[oid]
            if abs(s['x']) > x_limit or abs(s['y']) > y_limit:
                outcomes.append({
                    'time': float(current_frame),
                    'kind': 'exit',
                    'entities': [oid],
                    'value': None,
                    'src': None
                })
                s['active'] = False
                exiting.append(oid)
        for oid in exiting:
            active_ids.remove(oid)

        # 3. Apply friction and update positions
        for oid in active_ids:
            s = states[oid]
            s['vx'] *= friction_per_frame
            s['vy'] *= friction_per_frame
            s['x'] += s['vx']
            s['y'] += s['vy']

        current_frame += 1

    return outcomes

