            frame = int(row['frame'])
            motion_by_obj[oid][frame] = {
                'x': float(row['x']), 'y': float(row['y']),
                'vx': float(row['vx']), 'vy': float(row['vy'])
            }

    # Time range
    if horizon is None:
        horizon = 127.0
    if start is None:
        start = 0.0

    start_frame = int(math.ceil(start))
    horizon_frame = int(horizon)

    # Build active objects list from inputs
    # Track when each object enters
    obj_entry_frame = {}  # oid -> frame when it enters
    active_objects = set()
    for inp in inputs:
        entry_time = int(inp['time'])
        for oid in inp['entities']:
            active_objects.add(oid)
            if oid not in obj_entry_frame or entry_time < obj_entry_frame[oid]:
                obj_entry_frame[oid] = entry_time

    if not active_objects:
        return []

    # Get all recorded frames
    all_recorded_frames = set()
    for _, frames_dict in motion_by_obj.items():
        all_recorded_frames.update(frames_dict.keys())
    all_recorded_frames = sorted(all_recorded_frames)

    # Initialize state for each object
    # State: {oid: {x, y, vx, vy, active, entry_frame}}
    states = {}

    for oid in active_objects:
        entry_frame = obj_entry_frame[oid]
        motion_frames = motion_by_obj.get(oid, {})

        if not motion_frames:
            continue

        available_frames = sorted(motion_frames.keys())

        # Find best frame to initialize from
        # Must be >= entry_frame
        valid_frames = [f for f in available_frames if f >= entry_frame]
        if not valid_frames:
            continue

        # Use the earliest valid frame
        init_frame = valid_frames[0]
        init_data = motion_frames[init_frame]

        # Initialize state at entry_frame (or start_frame if later)
        actual_init_frame = max(entry_frame, start_frame)

        # Interpolate to actual_init_frame
        if init_frame == actual_init_frame:
            x, y, vx, vy = init_data['x'], init_data['y'], init_data['vx'], init_data['vy']
        else:
            # Advance from init_frame to actual_init_frame
            dt = actual_init_frame - init_frame
            vx = init_data['vx']
            vy = init_data['vy']
            x = init_data['x'] + vx * dt
            y = init_data['y'] + vy * dt

        states[oid] = {
            'x': x, 'y': y, 'vx': vx, 'vy': vy,
            'active': True, 'entry_frame': entry_frame
        }

    if not states:
        return []

    active_ids = sorted(states.keys())

    # Physics parameters
    friction_per_frame = 0.94  # Estimated from data
    collision_dist = 0.5  # Collision threshold
    x_limit = 7.0  # Exit boundary
    y_limit = 5.5

    # Simulate frame by frame
    current_frame = start_frame
    outcomes = []
    seen_collisions = set()

    while current_frame <= horizon_frame:
        # 1. Activate objects that enter this frame
        new_entries = []
        for oid in list(active_ids):
            if states[oid]['entry_frame'] == current_frame and not states[oid]['active']:
                # Re-initialize from motion log if available
                motion_frames = motion_by_obj.get(oid, {})
                if current_frame in motion_frames:
                    s = motion_frames[current_frame]
                    states[oid] = {
                        'x': s['x'], 'y': s['y'],
                        'vx': s['vx'], 'vy': s['vy'],
                        'active': True, 'entry_frame': current_frame
                    }
                else:
                    # Find closest frame
                    frames = sorted(motion_frames.keys())
                    closest = min(frames, key=lambda f: abs(f - current_frame))
                    s = motion_frames[closest]
                    dt = current_frame - closest
                    states[oid] = {
                        'x': s['x'] + s['vx'] * dt,
                        'y': s['y'] + s['vy'] * dt,
                        'vx': s['vx'], 'vy': s['vy'],
                        'active': True, 'entry_frame': current_frame
                    }
                new_entries.append(oid)

        # 2. Collision detection
        for i in range(len(active_ids)):
            for j in range(i + 1, len(active_ids)):
                o1, o2 = active_ids[i], active_ids[j]
                s1, s2 = states[o1], states[o2]

                if not s1['active'] or not s2['active']:
                    continue

                dx = s1['x'] - s2['x']
                dy = s1['y'] - s2['y']
                dist = math.sqrt(dx*dx + dy*dy)

                if dist < collision_dist and dist > 0.01:
                    key = (min(o1, o2), max(o1, o2), current_frame)
                    if key not in seen_collisions:
                        seen_collisions.add(key)
                        outcomes.append({
                            'time': float(current_frame),
                            'kind': 'collision',
                            'entities': [o1, o2],
                            'value': None,
                            'src': None
                        })

                        # Elastic collision (equal mass, perfect elasticity)
                        nx, ny = dx/dist, dy/dist
                        dvx = s1['vx'] - s2['vx']
                        dvy = s1['vy'] - s2['vy']
                        rel_vn = dvx*nx + dvy*ny

                        if rel_vn < 0:  # Approaching
                            s1['vx'] -= rel_vn * nx
                            s1['vy'] -= rel_vn * ny
                            s2['vx'] += rel_vn * nx
                            s2['vy'] += rel_vn * ny

        # 3. Check for exits (objects leaving scene)
        exiting = []
        for oid in active_ids:
            s = states[oid]
            if abs(s['x']) > x_limit or abs(s['y']) > y_limit:
                outcomes.append({
                    'time': float(current_frame),
                    'kind': 'exit',
                    'entities': [oid],
                    'value': None,
                    'src': None
                })
                s['active'] = False
                exiting.append(oid)
        for oid in exiting:
            active_ids.remove(oid)

        # 4. Apply friction and update positions
        for oid in active_ids:
            s = states[oid]
            s['vx'] *= friction_per_frame
            s['vy'] *= friction_per_frame
            s['x'] += s['vx']
            s['y'] += s['vy']

        current_frame += 1

    return outcomes

