import re
import math
from collections import defaultdict


def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_speed_threshold", 0.1)

    # Read motion log from document
    scope_node = node_by_title(doc, scope)
    child_nodes = children(doc, scope_node)
    motion_node = None
    for node in child_nodes:
        if 'Motion log' in node['title'] and node['kind'] == 'table':
            motion_node = node

    # motion_by_obj[oid][frame] = {x, y, vx, vy}
    motion_by_obj = defaultdict(dict)
    if motion_node:
        for _, row in table_rows(motion_node):
            obj_str = row['object']
            oid = obj_str.split()[0]
            frame = int(row['frame'])
            motion_by_obj[oid][frame] = {
                'x': float(row['x']), 'y': float(row['y']),
                'vx': float(row['vx']), 'vy': float(row['vy'])
            }

    # Determine time range
    if horizon is None:
        horizon = 127.0
    if start is None:
        start = 0.0

    # Active objects from inputs ONLY
    active_objects = set()
    for inp in inputs:
        for oid in inp['entities']:
            active_objects.add(oid)

    if not active_objects:
        return []

    outcomes = []
    seen_collisions = set()

    active_list = sorted(active_objects)

    # Detect collisions: find frames where two active objects are close (< 0.5)
    for i in range(len(active_list)):
        for j in range(i + 1, len(active_list)):
            o1, o2 = active_list[i], active_list[j]

            if o1 not in motion_by_obj or o2 not in motion_by_obj:
                continue

            frames1 = sorted(motion_by_obj[o1].keys())
            frames2 = sorted(motion_by_obj[o2].keys())
            common = sorted(set(frames1) & set(frames2))

            if not common:
                continue

            for f in common:
                p1 = motion_by_obj[o1][f]
                p2 = motion_by_obj[o2][f]
                dist = math.sqrt((p1['x'] - p2['x'])**2 + (p1['y'] - p2['y'])**2)

                # Collision threshold based on observed data (~0.4-0.5)
                if dist < 0.5:
                    # Verify by checking velocity change
                    # Get velocities before and after this frame
                    prev_frames = [ff for ff in common if ff < f]
                    next_frames = [ff for ff in common if ff > f]

                    is_collision = True
                    # If we can check velocities, verify there's a change
                    if prev_frames and next_frames:
                        prev_f = max(prev_frames)
                        next_f = min(next_frames)

                        v1_prev = motion_by_obj[o1].get(prev_f, {})
                        v1_next = motion_by_obj[o1].get(next_f, {})
                        v2_prev = motion_by_obj[o2].get(prev_f, {})
                        v2_next = motion_by_obj[o2].get(next_f, {})

                        if v1_prev and v1_next and v2_prev and v2_next:
                            dv1 = math.sqrt((v1_next['vx'] - v1_prev['vx'])**2 + 
                                           (v1_next['vy'] - v1_prev['vy'])**2)
                            dv2 = math.sqrt((v2_next['vx'] - v2_prev['vx'])**2 + 
                                           (v2_next['vy'] - v2_prev['vy'])**2)
                            # At least some velocity change expected
                            if dv1 < 0.15 and dv2 < 0.15:
                                is_collision = False

                    if is_collision:
                        key = (o1, o2, f)
                        if key not in seen_collisions:
                            seen_collisions.add(key)
                            outcomes.append({
                                'time': float(f),
                                'kind': 'collision',
                                'entities': [o1, o2],
                                'value': None,
                                'src': None
                            })

    # Detect exits: objects that stop being recorded before frame 127
    # and whose last position is near the visible area boundary
    for oid in active_objects:
        if oid not in motion_by_obj:
            continue

        frames = sorted(motion_by_obj[oid].keys())
        if not frames:
            continue

        last_frame = max(frames)

        # Only consider exits that happen after start
        if last_frame < start:
            continue

        # Object exits if it stops being recorded before video end
        # and is near the boundary
        if last_frame < 127:
            last_pos = motion_by_obj[oid][last_frame]
            # Boundary thresholds based on observed data
            if abs(last_pos['x']) > 5.5 or abs(last_pos['y']) > 4.0:
                outcomes.append({
                    'time': float(last_frame),
                    'kind': 'exit',
                    'entities': [oid],
                    'value': None,
                    'src': None
                })

    # Filter outcomes by start and horizon
    start_val = start if start is not None else 0
    horizon_val = horizon if horizon is not None else 127

    outcomes = [o for o in outcomes if start_val <= o['time'] <= horizon_val]

    return sorted(outcomes, key=lambda x: (x['time'], tuple(sorted(x['entities']))))

